import networkx as nx
G = nx.Graph()
for i in range(28):
    for j in range(i+1, 28):
        if len(list(G.neighbors(i))) < 7 and len(list(G.neighbors(j))) < 7:
            G.add_edge(i, j)
            if len(list(G.neighbors(i))) == 4 or len(list(G.neighbors(j))) == 4:
                break
print(G.edges())
